import datetime
from pydantic import BaseModel
from dataclasses import dataclass
from typing import List, Optional
from enum import Enum
from asyncio.subprocess import Process
from _io import TextIOWrapper


class ServiceBasicInfo(BaseModel):
    pid: int
    release: str
    url: str


class ServiceDetails(BaseModel):
    service: ServiceBasicInfo
    access_layer: Optional[str]
    bootup_duration_sec: Optional[float]
    start_time: Optional[datetime.datetime]
    logs: Optional[List[str]]


class ReleasePackage(BaseModel):
    ver: str
    python_ver: str
    os_name: str
    ue_type: str
    os_ver: str
    rel_format: str


class ArtifactoryLink(BaseModel):
    proxy_mngr_artifactory: str


class LatestPackage(BaseModel):
    ue_type: str
    rel_format: str


class AutoUpdate(BaseModel):
    method: str


class StartUeproxyServer(BaseModel):
    release_package: ReleasePackage
    port: str


class UeproxyServerDetails(BaseModel):
    port: int


class ProxyServiceStatus(str, Enum):
    STARTING = 'starting'
    DELETING = 'deleting'
    ACTIVE = 'active'
    INACTIVE = 'inactive'


@dataclass
class ServicePoolDetails:
    info: Optional[ServiceDetails]
    process: Optional[Process]
    console: Optional[TextIOWrapper]
    status: ProxyServiceStatus
    tests_in_progress: int
